22	pub(crate) struct CodeActionRequestHandler;
23	
24	impl RequestHandler for CodeActionRequestHandler {
25	    type RequestType = req::CodeActionRequest;
26	}
27	
28	impl BackgroundDocumentRequestHandler for CodeActionRequestHandler {
29	    fn document_url(params: &types::CodeActionParams) -> Cow<'_, Url> {
30	        Cow::Borrowed(&params.text_document.uri)
31	    }
32	
33	    fn run_with_snapshot(
34	        db: &ProjectDatabase,
35	        snapshot: &DocumentSnapshot,
36	        _client: &Client,
37	        params: types::CodeActionParams,
38	    ) -> Result<Option<types::CodeActionResponse>> {
39	        let diagnostics = params.context.diagnostics;
40	
41	        let Some(file) = snapshot.to_notebook_or_file(db) else {
42	            return Ok(None);
43	        };
44	        let mut actions = Vec::new();
45	
46	        for mut diagnostic in diagnostics.into_iter().filter(|diagnostic| {
47	            diagnostic.source.as_deref() == Some(DIAGNOSTIC_NAME)
48	                && range_intersect(&diagnostic.range, &params.range)
49	        }) {
50	            // If the diagnostic includes fixes, offer those up as options.
51	            if let Some(data) = diagnostic.data.take() {
52	                let data: DiagnosticData = match serde_json::from_value(data) {
53	                    Ok(data) => data,
54	                    Err(err) => {
55	                        tracing::warn!("Failed to deserialize diagnostic data: {err}");
56	                        continue;
57	                    }
58	                };
59	
60	                actions.push(CodeActionOrCommand::CodeAction(lsp_types::CodeAction {
61	                    title: data.fix_title,
62	                    kind: Some(CodeActionKind::QUICKFIX),
63	                    diagnostics: Some(vec![diagnostic.clone()]),
64	                    edit: Some(lsp_types::WorkspaceEdit {
65	                        changes: Some(data.edits),
66	                        document_changes: None,
67	                        change_annotations: None,
68	                    }),
69	                    is_preferred: Some(true),
70	                    command: None,
71	                    disabled: None,
72	                    data: None,
73	                }));
74	            }
75	
76	            // Try to find other applicable actions.
77	            //
78	            // This is only for actions that are messy to compute at the time of the diagnostic.
79	            // For instance, suggesting imports requires finding symbols for the entire project,
80	            // which is dubious when you're in the middle of resolving symbols.
81	            let url = snapshot.url();
82	            let encoding = snapshot.encoding();
83	            if let Some(NumberOrString::String(diagnostic_id)) = &diagnostic.code
84	                && let Some(range) = diagnostic.range.to_text_range(db, file, url, encoding)
85	            {
86	                for action in code_actions(db, file, range, diagnostic_id) {
87	                    actions.push(CodeActionOrCommand::CodeAction(lsp_types::CodeAction {
88	                        title: action.title,
89	                        kind: Some(CodeActionKind::QUICKFIX),
90	                        diagnostics: Some(vec![diagnostic.clone()]),
91	                        edit: Some(lsp_types::WorkspaceEdit {
92	                            changes: to_lsp_edits(db, file, encoding, action.edits),
93	                            document_changes: None,
94	                            change_annotations: None,
95	                        }),
96	                        is_preferred: Some(action.preferred),
97	                        command: None,
98	                        disabled: None,
99	                        data: None,
100	                    }));
101	                }
102	            }
103	        }
104	
105	        if actions.is_empty() {
106	            Ok(None)
107	        } else {
108	            Ok(Some(actions))
109	        }
110	    }
111	}
112	
113	fn to_lsp_edits(
114	    db: &dyn Db,
115	    file: File,
116	    encoding: PositionEncoding,
117	    edits: Vec<Edit>,
118	) -> Option<HashMap<Url, Vec<TextEdit>>> {
119	    let mut lsp_edits: HashMap<Url, Vec<lsp_types::TextEdit>> = HashMap::new();
120	
121	    for edit in edits {
122	        let location = edit
123	            .range()
124	            .to_lsp_range(db, file, encoding)?
125	            .to_location()?;
126	
127	        lsp_edits
128	            .entry(location.uri)
129	            .or_default()
130	            .push(lsp_types::TextEdit {
131	                range: location.range,
132	                new_text: edit.content().unwrap_or_default().to_string(),
133	            });
134	    }
135	
136	    Some(lsp_edits)
137	}
138	
139	fn range_intersect(range: &lsp_types::Range, other: &lsp_types::Range) -> bool {
140	    let start = range.start.max(other.start);
141	    let end = range.end.min(other.end);
142	    end >= start
143	}
