20	impl BackgroundDocumentRequestHandler for HoverRequestHandler {
21	    fn document_url(params: &HoverParams) -> Cow<'_, Url> {
22	        Cow::Borrowed(&params.text_document_position_params.text_document.uri)
23	    }
24	
25	    fn run_with_snapshot(
26	        db: &ProjectDatabase,
27	        snapshot: &DocumentSnapshot,
28	        _client: &Client,
29	        params: HoverParams,
30	    ) -> crate::server::Result<Option<lsp_types::Hover>> {
31	        if snapshot
32	            .workspace_settings()
33	            .is_language_services_disabled()
34	        {
35	            return Ok(None);
36	        }
37	
38	        let Some(file) = snapshot.to_notebook_or_file(db) else {
39	            return Ok(None);
40	        };
41	
42	        let Some(offset) = params.text_document_position_params.position.to_text_size(
43	            db,
44	            file,
45	            snapshot.url(),
46	            snapshot.encoding(),
47	        ) else {
48	            return Ok(None);
49	        };
50	
51	        let Some(range_info) = hover(db, file, offset) else {
52	            return Ok(None);
53	        };
54	
55	        let (markup_kind, lsp_markup_kind) = if snapshot
56	            .resolved_client_capabilities()
57	            .prefers_markdown_in_hover()
58	        {
59	            (MarkupKind::Markdown, lsp_types::MarkupKind::Markdown)
60	        } else {
61	            (MarkupKind::PlainText, lsp_types::MarkupKind::PlainText)
62	        };
63	
64	        let contents = range_info.display(db, markup_kind).to_string();
65	
66	        Ok(Some(lsp_types::Hover {
67	            contents: HoverContents::Markup(MarkupContent {
68	                kind: lsp_markup_kind,
69	                value: contents,
70	            }),
71	            range: range_info
72	                .file_range()
73	                .to_lsp_range(db, snapshot.encoding())
74	                .map(|lsp_range| lsp_range.local_range()),
75	        }))
76	    }
77	}
